D=Document(); sec=D.sections[0]; sec.top_margin=Cm(2.5); sec.bottom_margin=Cm(2.5); sec.left_margin=Cm(2.5); sec.right_margin=Cm(2.5)
normal=D.styles['Normal']; normal.font.name='Arial'; normal.font.size=Pt(11); normal.paragraph_format.line_spacing=1.5
for name in ['Title','Heading 1','Heading 2']:
 st=D.styles[name]; st.font.name='Arial'; st.font.color.rgb=None
p=D.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run('GUION TÉCNICO Y NARRATIVO'); r.bold=True; r.font.name='Arial'; r.font.size=Pt(20)
p=D.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run('RentaSmart · Fase 4 · Equipo 09\nDuración prevista: 12 minutos 15 segundos').font.name='Arial'
D.add_paragraph('Guía de grabación',style='Heading 1'); D.add_paragraph('El tiempo incluye pausas para cambiar diapositivas y mostrar la interfaz. Mantengan visible la etiqueta “prototipo local” durante la demostración. No presenten métricas como precisión sobre viviendas individuales. El tablero no está publicado en línea.')
for tm,title,speaker,visual,text in scenes:
 D.add_paragraph(f'{tm} | {title}',style='Heading 1')
 p=D.add_paragraph(); p.add_run('Voz: ').bold=True; p.add_run(speaker)
 p=D.add_paragraph(); p.add_run('Visual: ').bold=True; p.add_run(visual)
 D.add_paragraph(text)
D.add_paragraph('Cierre de producción',style='Heading 1'); D.add_paragraph('Antes de grabar, abrir dashboard/index.html, probar los filtros, buscar una colonia, cambiar el área de 70 m² y alternar casa/departamento. Grabar la pantalla sin notificaciones ni datos privados. El equipo debe publicar el video como público o no listado y verificar una duración entre 10 y 15 minutos. El enlace se incorpora al informe después de subirlo.')
docx=OUT/'Guion_Video_RentaSmart_Fase4.docx'; D.save(docx)
# Matching PDF handout
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='Bodyx',parent=styles['BodyText'],fontName='Helvetica',fontSize=10.5,leading=15.5,alignment=TA_JUSTIFY,spaceAfter=8)); styles.add(ParagraphStyle(name='Hx',parent=styles['Heading1'],fontName='Helvetica-Bold',fontSize=15,leading=19,textColor=colors.HexColor('#17324D'),spaceBefore=10,spaceAfter=7)); styles.add(ParagraphStyle(name='Subx',parent=styles['Normal'],fontName='Helvetica',fontSize=10,leading=15,alignment=TA_CENTER,textColor=colors.HexColor('#53687A')))
flow=[Spacer(1,1.4*cm),Paragraph('GUION TÉCNICO Y NARRATIVO',ParagraphStyle(name='Titx',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=22,textColor=colors.HexColor('#17324D'),alignment=TA_CENTER)),Paragraph('RentaSmart · Fase 4 · Equipo 09<br/>Duración prevista: 12 minutos 15 segundos',styles['Subx']),Spacer(1,.5*cm),Paragraph('<b>Grabación:</b> el tiempo incluye pausas para cambiar diapositivas y mostrar la interfaz. Mantengan visible “prototipo local”. No presenten métricas como precisión sobre viviendas individuales. El tablero aún no está publicado.',styles['Bodyx'])]
for tm,title,speaker,visual,text in scenes:
 flow.append(KeepTogether([Paragraph(f'{tm} | {title}',styles['Hx']),Paragraph(f'<b>Voz:</b> {speaker}<br/><b>Visual:</b> {visual}',styles['Bodyx']),Paragraph(text,styles['Bodyx'])]))
flow += [Paragraph('Cierre de producción',styles['Hx']),Paragraph('Antes de grabar, abrir dashboard/index.html, probar filtros, buscar una colonia, cambiar el área de 70 m² y alternar casa/departamento. Grabar sin notificaciones ni datos privados. Después de subir el video como público o no listado, verificar que dure de 10 a 15 minutos y agregar el enlace al informe.',styles['Bodyx'])]
SimpleDocTemplate(str(OUT/'Guion_Video_RentaSmart_Fase4.pdf'),pagesize=letter,rightMargin=2.5*cm,leftMargin=2.5*cm,topMargin=2.2*cm,bottomMargin=2*cm,title='Guion video RentaSmart').build(flow)
